#!/usr/bin/env node

import { spawnSync } from "node:child_process";
import { dirname, isAbsolute, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");

function pnpmInvocation() {
  if (process.platform !== "win32") {
    return { executable: "pnpm", prefixArguments: [] };
  }
  const scriptPath = process.env.npm_execpath;
  if (!scriptPath || !isAbsolute(scriptPath) || !/\.[cm]?js$/u.test(scriptPath)) {
    throw new Error(
      "Windows MCP tests must run through a pnpm lifecycle with an absolute JavaScript npm_execpath",
    );
  }
  return { executable: process.execPath, prefixArguments: [scriptPath] };
}

const pnpm = pnpmInvocation();

function run(executable, args, options = {}) {
  const result = spawnSync(executable, args, {
    cwd: repoRoot,
    encoding: "utf8",
    stdio: "inherit",
    ...options,
  });
  if (result.error) throw result.error;
  if (result.status !== 0) process.exit(result.status ?? 1);
}

export function runMcpTest(testFile) {
  run(process.execPath, ["scripts/verify-mcpfn-adoption.mjs"]);
  run(pnpm.executable, [
    ...pnpm.prefixArguments,
    "--filter",
    "@skillplane/mcp...",
    "build",
  ]);
  run(
    pnpm.executable,
    [
      ...pnpm.prefixArguments,
      "--filter",
      "@skillplane/mcp",
      "exec",
      "vitest",
      "run",
      "--exclude",
      "dist/**",
      testFile,
    ],
    {
      env: {
        ...process.env,
        NODE_OPTIONS: [process.env.NODE_OPTIONS, "--conditions=development"]
          .filter(Boolean)
          .join(" "),
      },
    },
  );
}
#!/usr/bin/env node

import { randomUUID } from "node:crypto";
import { rm } from "node:fs/promises";
import { resolve } from "node:path";
import { isMain, root, run } from "./lib/production-deployment.mjs";
import { renderDevelopmentTopologyConfigs } from "./render-development-topology-config.mjs";

export async function dryRunDevelopmentTopologyConfigs(options = {}) {
  const outputDirectory = resolve(
    root,
    ".data",
    "development-topology-config-dry-run",
    randomUUID(),
  );
  const rendered = await renderDevelopmentTopologyConfigs({
    controlHyperdriveId: "1".repeat(32),
    publicBucketName: "skillplane-public-bundles-dev",
    publicTurnstileSiteKey: "development-self-test-site-key",
    postHogProjectToken: `phc_${"d".repeat(32)}`,
    cells: {
      "in-south": {
        hyperdriveId: "2".repeat(32),
        bucketName: "skillplane-skill-bundles-dev",
      },
      "us-east": {
        hyperdriveId: "3".repeat(32),
        bucketName: "skillplane-us-east-bundles-dev",
      },
      "eu-west": {
        hyperdriveId: "4".repeat(32),
        bucketName: "skillplane-eu-west-bundles-dev",
      },
    },
    ...options,
  });
  try {
    for (const output of rendered.outputs) {
      run(
        "pnpm",
        [
          "exec",
          "wrangler",
          "deploy",
          "--config",
          `${root}/${output.path}`,
          "--dry-run",
          "--strict",
          "--outdir",
          resolve(outputDirectory, output.id.replaceAll(":", "-")),
        ],
        {
          cwd: `${root}/${output.directory}`,
          failureMessage: `${output.id} development topology dry-run failed`,
        },
      );
    }
    return { ok: true, workers: rendered.outputs.map((output) => output.id) };
  } finally {
    await rm(outputDirectory, { recursive: true, force: true });
  }
}

if (isMain(import.meta.url)) {
  process.stdout.write(
    `${JSON.stringify(await dryRunDevelopmentTopologyConfigs(), null, 2)}\n`,
  );
}
#!/usr/bin/env node

import { deployDevelopmentTopology } from "./lib/development-topology-deployment.mjs";
import { isMain } from "./lib/production-deployment.mjs";

export { deployDevelopmentTopology };

export function parseOnlyKinds(args) {
  const onlyIndex = args.indexOf("--only");
  const onlyKinds = onlyIndex < 0 ? undefined : (args[onlyIndex + 1] ?? "").split(",");
  const allowed = new Set(["app", "mcp", "projection", "datafn"]);
  if (
    onlyKinds &&
    (onlyKinds.length === 0 || onlyKinds.some((kind) => !allowed.has(kind)))
  ) {
    throw new Error("--only must contain app, mcp, projection, or datafn");
  }
  return onlyKinds;
}

if (isMain(import.meta.url)) {
  const onlyKinds = parseOnlyKinds(process.argv.slice(2));
  process.stdout.write(
    `${JSON.stringify(await deployDevelopmentTopology({ onlyKinds }), null, 2)}\n`,
  );
}
